package main

import (
	"fmt"
	"os"
)

func PrintPrompt() {
	fmt.Print("$ ")
	os.Stdout.Sync()
}

package main

import (
	"bufio"
	"io"
)

func ReadInput(r io.Reader) string {
	scanner := bufio.NewScanner(r)
	if scanner.Scan() {
		return scanner.Text()
	}
	return ""
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	for {
		fmt.Print("$ ")
		if !scanner.Scan() {
			break
		}
		input := strings.TrimSpace(scanner.Text())
		if input == "exit" {
			break
		}
	}
}
